<div class="customer-heading employee-heading"><div><div class="breadcrumb-line">Home <span>&rsaquo;</span> Employees <span>&rsaquo;</span> <b>Salary Management</b></div><h1>Salary Management</h1><p class="text-muted mb-0">Calculate, review and manage employee salary payments.</p></div><a href="index.php?page=admin&amp;section=employees-salary&amp;salary_add=1" class="btn btn-primary customer-add-button">+ Calculate Salary</a></div>
<div class="admin-panel salary-filter-panel"><form method="get" class="row g-3 align-items-end"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="employees-salary"><div class="col-md-4"><label class="form-label">Employee</label><select class="form-select" name="salary_employee_id"><option value="0">All Employees</option><?php foreach ($salaryEmployeeOptions as $option): ?><option value="<?= (int)$option['id'] ?>" <?= $salaryEmployeeFilter === (int)$option['id'] ? 'selected' : '' ?>><?= e($option['name'].' ('.$option['employee_code'].')') ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Month From</label><input class="form-control" type="month" name="salary_month_from" value="<?= e($salaryMonthFrom) ?>"></div><div class="col-md-2"><label class="form-label">Month To</label><input class="form-control" type="month" name="salary_month_to" value="<?= e($salaryMonthTo) ?>"></div><div class="col-md-2"><label class="form-label">Status</label><select class="form-select" name="salary_status"><option value="">All Statuses</option><option value="pending" <?= $salaryStatusFilter === 'pending' ? 'selected' : '' ?>>Pending</option><option value="paid" <?= $salaryStatusFilter === 'paid' ? 'selected' : '' ?>>Paid</option></select></div><div class="col-md-2 d-flex gap-2"><button class="btn btn-primary flex-grow-1" type="submit">Filter</button><a class="btn btn-light" href="index.php?page=admin&amp;section=employees-salary">Reset</a></div></form></div>
<div class="admin-panel supplier-list-panel"><div class="panel-heading"><h2>Salary History</h2><span class="text-muted"><?= count($salaryRows) ?> record<?= count($salaryRows) === 1 ? '' : 's' ?></span></div><div class="table-responsive"><table class="table admin-table supplier-table"><thead><tr><th>Employee</th><th>Month</th><th>Basic Salary</th><th>Deduction</th><th>Net Salary</th><th>Status</th><th>Payment</th><th>Actions</th></tr></thead><tbody><?php if(!$salaryRows): ?><tr><td colspan="8" class="empty-table">No salary records match the selected filters.</td></tr><?php else: foreach($salaryRows as $salary): ?><tr><td><strong><?= e($salary['employee_name']) ?></strong><small class="d-block text-muted"><?= e($salary['employee_code']) ?></small></td><td><?= e(date('F Y',strtotime($salary['salary_month']))) ?></td><td><?= number_format((float)$salary['basic_salary'],2) ?></td><td><?= number_format((float)$salary['deductions'],2) ?></td><td><strong><?= number_format((float)$salary['net_salary'],2) ?></strong></td><td><span class="status-badge status-<?= e($salary['status']) ?>"><?= e(ucfirst($salary['status'])) ?></span></td><td><?php if($salary['status']==='pending'): ?><a class="btn btn-sm btn-primary" href="index.php?page=admin&amp;section=employees-salary&amp;salary_pay_id=<?= (int)$salary['id'] ?>">Pay</a><?php else: ?><small class="text-muted d-block"><?= e($salary['paid_at'] ?: '-') ?></small><?php endif; ?></td><td><div class="action-links employee-actions"><a href="index.php?page=admin&amp;section=employees-salary&amp;salary_view_id=<?= (int)$salary['id'] ?>" title="View salary" aria-label="View salary">&#128065;</a><a href="index.php?page=admin&amp;section=employees-salary&amp;salary_edit_id=<?= (int)$salary['id'] ?>" title="Edit salary" aria-label="Edit salary">&#9998;</a><?php if($salary['status']==='pending'): ?><form method="post" action="index.php?page=admin&amp;section=employees-salary" onsubmit="return confirm('Delete this pending salary record?');"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="salary_id" value="<?= (int)$salary['id'] ?>"><input type="hidden" name="salary_action" value="delete"><button type="submit" title="Delete salary" aria-label="Delete salary">&#128465;</button></form><?php else: ?><span class="action-disabled" title="Paid salary cannot be deleted">&#128274;</span><?php endif; ?><a href="index.php?page=admin&amp;section=employees-salary&amp;receipt_id=<?= (int)$salary['id'] ?>&amp;receipt_mode=download" title="Download receipt" aria-label="Download receipt">&#128190;</a></div></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
